const DB='imagine-four-settings',STORE='settings';
async function db(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB,1);r.onupgradeneeded=()=>r.result.createObjectStore(STORE);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('기기 저장 공간이 다른 창에서 사용 중이에요.'));});}
export async function readSaved(){const d=await db();try{return await new Promise((resolve,reject)=>{const t=d.transaction(STORE,'readonly'),r=t.objectStore(STORE).get('preset');r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(r.error);});}finally{d.close();}}
export async function saveSettings(preset,backgrounds,logo=null){const size=backgrounds.reduce((n,a)=>n+a.blob.size,0);if(backgrounds.length>20||size>50*1024*1024)throw Error('배경은 20개, 합계 50MB까지 저장할 수 있어요.');const d=await db();try{await new Promise((resolve,reject)=>{const t=d.transaction(STORE,'readwrite');t.objectStore(STORE).put({preset,backgrounds,logo},'preset');t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error||Error('저장 공간을 확인해 주세요.'));});}finally{d.close();}}
export async function clearSaved(){const d=await db();try{await new Promise((resolve,reject)=>{const t=d.transaction(STORE,'readwrite');t.objectStore(STORE).clear();t.oncomplete=resolve;t.onerror=()=>reject(t.error);});}finally{d.close();}}
